28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 format")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    @Email
54	    private String email;
55	
56	    @Column(name = "postcode")
57	    @Pattern(regexp = "^[0-9]{4}$", message = "Postcode must be 4 digits")
58	    private String postcode;
59	
60	    @Column(name = "registration_date")
61	    private LocalDate registrationDate;
62	
63	    @Column(name = "customer_code")
64	    private String customerCode;
65	
66	    @Column(name = "household_id")
67	    private String householdId;
68	
69	    @Column(name = "namesake_count")
70	    private Integer namesakeCount;
71	
72	    @Column(name = "household_size")
73	    private Integer householdSize;
74	
75	    @Column(name = "bulk_signup_warning")
76	    private Boolean bulkSignupWarning;
77	
78	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
79	    private Set<Pet> pets;
80	
81	    public String getAddress() {
82	        return this.address;
83	    }
84	
85	    public void setAddress(String address) {
86	        this.address = address;
87	    }
88	
89	    public String getCity() {
90	        return this.city;
91	    }
92	
93	    public void setCity(String city) {
94	        this.city = city;
95	    }
96	
97	    public String getTelephone() {
98	        return this.telephone;
99	    }
100	
101	    public void setTelephone(String telephone) {
102	        this.telephone = telephone;
103	    }
104	
105	    public String getEmail() {
106	        return this.email;
107	    }
108	
109	    public void setEmail(String email) {
110	        this.email = email;
111	    }
112	
113	    public String getPostcode() {
114	        return this.postcode;
115	    }
116	
117	    public void setPostcode(String postcode) {
118	        this.postcode = postcode;
119	    }
120	
121	    public LocalDate getRegistrationDate() {
122	        return this.registrationDate;
123	    }
124	
125	    public void setRegistrationDate(LocalDate registrationDate) {
126	        this.registrationDate = registrationDate;
127	    }
128	
129	    public String getCustomerCode() {
130	        return this.customerCode;
131	    }
132	
133	    public void setCustomerCode(String customerCode) {
134	        this.customerCode = customerCode;
135	    }
136	
137	    public String getHouseholdId() {
138	        return this.householdId;
139	    }
140	
141	    public void setHouseholdId(String householdId) {
142	        this.householdId = householdId;
143	    }
144	
145	    public Integer getNamesakeCount() {
146	        return this.namesakeCount;
147	    }
148	
149	    public void setNamesakeCount(Integer namesakeCount) {
150	        this.namesakeCount = namesakeCount;
151	    }
152	
153	    public Integer getHouseholdSize() {
154	        return this.householdSize;
155	    }
156	
157	    public void setHouseholdSize(Integer householdSize) {
158	        this.householdSize = householdSize;
159	    }
160	
161	    public Boolean getBulkSignupWarning() {
162	        return this.bulkSignupWarning;
163	    }
164	
165	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
166	        this.bulkSignupWarning = bulkSignupWarning;
167	    }
168	
169	    protected Set<Pet> getPetsInternal() {
170	        if (this.pets == null) {
171	            this.pets = new HashSet<>();
172	        }
173	        return this.pets;
174	    }
175	
176	    protected void setPetsInternal(Set<Pet> pets) {
177	        this.pets = pets;
178	    }
179	
180	    public List<Pet> getPets() {
181	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
182	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
183	        return Collections.unmodifiableList(sortedPets);
184	    }
185	
186	    public void setPets(List<Pet> pets) {
187	        this.pets = new HashSet<>(pets);
188	    }
189	
190	    public void addPet(Pet pet) {
191	        getPetsInternal().add(pet);
192	        pet.setOwner(this);
193	    }
194	
195	    /**
196	     * Return the Pet with the given name, or null if none found for this Owner.
197	     *
198	     * @param name to test
199	     * @return true if pet name is already in use
200	     */
201	    public Pet getPet(String name) {
202	        return getPet(name, false);
203	    }
204	
205	    /**
206	     * Return the Pet with the given name, or null if none found for this Owner.
207	     *
208	     * @param name to test
209	     * @return true if pet name is already in use
210	     */
211	    public Pet getPet(String name, boolean ignoreNew) {
212	        name = name.toLowerCase();
213	        for (Pet pet : getPetsInternal()) {
214	            if (!ignoreNew || !pet.isNew()) {
215	                String compName = pet.getName();
216	                compName = compName.toLowerCase();
217	                if (compName.equals(name)) {
218	                    return pet;
219	                }
220	            }
221	        }
222	        return null;
223	    }
224	
225	    public Pet getPet(Integer petId) {
226	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
227	    }
228	
229	    @Override
230	    public String toString() {
231	        return new ToStringCreator(this)
232	
233	            .append("id", this.getId())
234	            .append("new", this.isNew())
235	            .append("lastName", this.getLastName())
236	            .append("firstName", this.getFirstName())
237	            .append("address", this.address)
238	            .append("city", this.city)
239	            .append("telephone", this.telephone)
240	            .append("email", this.email)
241	            .toString();
242	    }
243	}
