1	package org.springframework.samples.petclinic.rest.escalation;
2	
3	/**
4	 * Thrown when a create- or update-owner request supplies a 4-digit postcode that is out of
5	 * range for the owner's city region. Handled by {@link InvalidPostcodeExceptionHandler}, which
6	 * responds 400.
7	 */
8	public class InvalidPostcodeException extends Exception {
9	
10	    public InvalidPostcodeException(String city, String postcode) {
11	        super("Postcode " + postcode + " is not valid for the region of city: " + city);
12	    }
13	}
