1	package org.springframework.samples.petclinic.rest.escalation;
2	
3	import net.officefloor.plugin.section.clazz.Parameter;
4	import net.officefloor.web.ObjectResponse;
5	import org.springframework.http.HttpStatus;
6	import org.springframework.http.ProblemDetail;
7	import org.springframework.http.ResponseEntity;
8	
9	public class InvalidPostcodeExceptionHandler {
10	
11	    public void handle(@Parameter InvalidPostcodeException ex,
12	            ObjectResponse<ResponseEntity<ProblemDetail>> response) {
13	        ProblemDetail detail = ProblemDetails.build(ex, HttpStatus.BAD_REQUEST, ex.getMessage());
14	        response.send(ResponseEntity.status(HttpStatus.BAD_REQUEST).body(detail));
15	    }
16	}
