15	
16	import java.util.Collection;
17	import java.util.List;
18	
19	/**
20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public interface OwnerMapper {
24	
25	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
26	    @Mapping(target = "initials", expression = "java(initials(owner))")
27	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
28	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
29	    @Mapping(target = "locality", expression = "java(locality(owner))")
30	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
31	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
32	    OwnerDto toOwnerDto(Owner owner);
33	
34	    /** The owner's derived duplicate-detection key - see {@link OwnerIdentities}. */
35	    default String identityKey(Owner owner) {
36	        if (owner == null) {
37	            return null;
38	        }
39	        return OwnerIdentities.of(owner);
40	    }
41	
42	    /** The owner's preferred contact channel - 'EMAIL' when an email is present, otherwise 'PHONE'. */
43	    default String contactPreference(Owner owner) {
44	        if (owner == null) {
45	            return null;
46	        }
47	        return ContactPreference.forOwner(owner).name();
48	    }
49	
50	    /** The canonical region derived from the owner's city via the fixed city-to-region table,
51	     * or 'UNKNOWN' when the city is not in the table. */
52	    default String locality(Owner owner) {
53	        if (owner == null) {
54	            return null;
55	        }
56	        return Locality.forCity(owner.getCity());
57	    }
58	
59	    /** Format the stored names as 'LastName, FirstName'. */
60	    default String displayName(Owner owner) {
61	        if (owner == null) {
62	            return null;
63	        }
64	        return owner.getLastName() + ", " + owner.getFirstName();
65	    }
66	
67	    /** The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot (e.g. 'J.S.'). */
68	    default String initials(Owner owner) {
69	        if (owner == null) {
70	            return null;
71	        }
72	        return initial(owner.getFirstName()) + initial(owner.getLastName());
73	    }
74	
75	    private static String initial(String name) {
76	        if (name == null || name.isEmpty()) {
77	            return "";
78	        }
79	        return Character.toUpperCase(name.charAt(0)) + ".";
80	    }
81	
82	    /**
83	     * The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
84	     * last two digits of the registrationDate year (e.g. 'LON-SMI-0007-M26'). Derived from the owner's
85	     * own fields; null until both the customer code and registration date are assigned.
86	     */
87	    default String membershipNumber(Owner owner) {
88	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
89	            return null;
90	        }
91	        return owner.getCustomerCode() + "-M" + String.format("%02d", owner.getRegistrationDate().getYear() % 100);
92	    }
93	
94	    /**
95	     * The owner's numeric membership level, derived from the owner's own fields; null when there
96	     * is no owner.
97	     *
98	     * @see MembershipLevel
99	     */
100	    default Integer membershipLevel(Owner owner) {
101	        if (owner == null) {
102	            return null;
103	        }
104	        return MembershipLevel.of(owner);
105	    }
106	
107	    Owner toOwner(OwnerDto ownerDto);
108	
109	    @Mapping(target = "id", ignore = true)
110	    @Mapping(target = "pets", ignore = true)
111	    Owner toOwner(OwnerFieldsDto ownerDto);
112	
113	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
114	
115	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
116	
117	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
118	        OwnerPageDto ownerPageDto = new OwnerPageDto();
119	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
120	        ownerPageDto.setPage(ownerPage.getNumber());
121	        ownerPageDto.setSize(ownerPage.getSize());
122	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
123	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
124	        return ownerPageDto;
125	    }
126	}
